(function applyV1124Adventurers() {
    const ALIAS = { '電閃雷鳴': '雷閃電鳴', '專注弱點': '黑暗狙擊' };
    const TIER_LEVEL = { 1: 10, 2: 30, 3: 70, 4: 120 };
    const NOTES = [];
    const note = (job, skill, text) => NOTES.push(job.split(' ')[0] + '／' + skill + '：' + text);
    const findSkill = (job, name) => {
        const names = [name, ALIAS[name]].filter(Boolean);
        const hits = [];
        for (const arr of Object.values(job.skills)) for (const s of arr) if (names.includes(s.name)) hits.push(s);
        return hits;
    };
    const blank = (v) => v == null || v === '無' || v === '刪除' || v === '-' || v === '';
    function resize(skill, max) {
        if (!max || skill.maxLevel === max && skill.levels.length === max + 1) return;
        const old = skill.maxLevel;
        skill.maxLevel = max;
        while (skill.levels.length <= max) skill.levels.push({ effect: '', fullDescription: '' });
        if (skill.levels.length > max + 1) skill.levels.length = max + 1;
        if (old && old !== max) note(skill._job || '', skill.name, '最高等級 ' + old + ' → ' + max);
    }
    function mergeLevels(jobName, skill, panels) {
        const labels = [];
        const removed = [];
        panels.forEach(p => p.stats.forEach(st => {
            labels.push(st.label);
            if (st.removed) removed.push(st.label);
        }));
        const dmgLabel = labels.some(l => /倍率|傷害/.test(l));
        const related = (k) => (dmgLabel && /攻擊力|威力|傷害/.test(k)) || labels.some(l => l === k || k.includes(l) || l.includes(k) || ['攻擊力','攻擊','魔力','防禦','傷害','持續','冷卻','次數','目標','倍率','鬥氣','機率','速度','恢復','命中','迴避','暴擊','減少','降低','時間','範圍','數量','經驗'].some(w => k.includes(w) && l.includes(w)));
        for (let i = 1; i <= skill.maxLevel; i++) {
            const lv = skill.levels[i] || { effect: '', fullDescription: '' };
            const parts = [];
            panels.forEach(p => {
                const idx = i - (p.from || 1);
                p.stats.forEach(st => {
                    if (st.removed) return;
                    if (idx < 0 || idx >= st.after.length) return;
                    const v = st.after[idx];
                    if (blank(v)) return;
                    const unit = st.unit && !String(v).endsWith(st.unit) ? st.unit : '';
                    parts.push(st.label + ': ' + v + unit);
                });
            });
            const keep = (lv.effect || '').split(/，|, ?/).map(x => x.trim()).filter(Boolean).filter(seg => {
                const k = seg.split(/[:：]/)[0].trim();
                return !related(k);
            });
            if (parts.length || removed.length) {
                lv.effect = keep.concat(parts).join('，');
                lv.fullDescription = ((skill.description || '').split('\n')[0]) + (lv.effect ? ' 等級' + i + '效果：' + lv.effect + '。' : '');
                skill.levels[i] = lv;
            }
        }
    }
    const pendingPre = [];
    Object.entries(V1124_ADV).forEach(([jobName, skills]) => {
        const job = allProfessionsData[jobName];
        if (!job) { NOTES.push(jobName + '：資料裡沒有這個職業'); return; }
        skills.forEach(sp => {
            const shown = sp.name || sp.oldName || sp.pid;
            if (!sp.name && !sp.deleted) { note(jobName, sp.pid, '頁面上這張卡沒有讀到技能名稱，沒有套用'); return; }
            if (sp.deleted) {
                const hits = findSkill(job, sp.oldName || sp.name);
                if (!hits.length) { note(jobName, shown, '頁面寫刪除，但正式版找不到同名技能'); return; }
                const ids = hits.map(s => s.id);
                Object.values(job.skills).forEach(arr => {
                    for (let i = arr.length - 1; i >= 0; i--) if (ids.includes(arr[i].id)) arr.splice(i, 1);
                });
                Object.values(job.skills).forEach(arr => arr.forEach(s => {
                    ids.forEach(id => { if (s.preRequisite && s.preRequisite[id] != null) delete s.preRequisite[id]; });
                }));
                note(jobName, shown, '已刪除');
                return;
            }
            let hits = findSkill(job, sp.oldName || sp.name);
            if (!hits.length && sp.name) hits = findSkill(job, sp.name);
            let skill = hits.length === 1 ? hits[0] : null;
            if (hits.length > 1) { note(jobName, shown, '同名技能超過一個，沒有自動改'); return; }
            if (!skill) {
                const tier = sp.tier;
                const stage = tier && job.jobStagesOrder[tier];
                if (!stage || !job.skills[stage]) { note(jobName, shown, '頁面有這張卡，但對不到轉職階段，沒有新增'); return; }
                skill = { id: 'v24_' + sp.pid, name: sp.name, maxLevel: sp.max || 1, requiredLevel: TIER_LEVEL[tier] || 10, preRequisite: {}, description: sp.desc || '', imageUrl: sp.icon || 'ui/mushroom.png', levels: [null], _v1124: true };
                for (let i = 1; i <= skill.maxLevel; i++) skill.levels.push({ effect: '', fullDescription: '' });
                job.skills[stage].push(skill);
                note(jobName, sp.name, '新增');
            } else if (sp.oldName && sp.name && sp.oldName !== sp.name) {
                note(jobName, sp.oldName + ' → ' + sp.name, '改名');
                skill.name = sp.name;
            }
            skill._job = jobName;
            if (sp.desc) skill.description = sp.desc;
            if (sp.max) resize(skill, sp.max);
            if (sp.panels && sp.panels.length) mergeLevels(jobName, skill, sp.panels);
            if (sp.rangeOnly && sp.rangeOnly.length) {
                const line = '官網這幾項只寫了區間，沒有每一級的數字，所以那些等級先留空：' + sp.rangeOnly.map(r => r.label + ' ' + r.text).join('、');
                if ((skill.description || '').indexOf(line) < 0) skill.description = (skill.description ? skill.description + '\n' : '') + line;
                note(jobName, skill.name, line);
            }
            (sp.extraNotes || []).forEach(line => {
                if ((skill.description || '').indexOf(line) < 0) skill.description = (skill.description ? skill.description + '\n' : '') + line;
                note(jobName, skill.name, line);
            });
            if (sp.preName) pendingPre.push([job, skill, sp.preName, sp.preLv, jobName]);
        });
    });
    pendingPre.forEach(([job, skill, preName, preLv, jobName]) => {
        let hits = findSkill(job, preName);
        if (!hits.length) {
            Object.values(job.skills).forEach(arr => arr.forEach(s => { if (s.name === preName) hits.push(s); }));
        }
        if (hits.length !== 1) { note(jobName, skill.name, '前置「' + preName + ' ' + preLv + '級」對不到技能，沒有改前置'); return; }
        skill.preRequisite = Object.assign({}, skill.preRequisite, { [hits[0].id]: preLv });
    });
    window.V1124_ADV_NOTES = NOTES;
})();
